using EnterpriseDocumentIntelligence.IndexingService.Domain; namespace EnterpriseDocumentIntelligence.IndexingService.Application; public interface IIndexStore{Task UpsertAsync(SearchIndexRecord record,CancellationToken ct=default);Task<SearchIndexRecord?> GetAsync(string id,CancellationToken ct=default);} public sealed class IndexingApplication(IIndexStore store){public Task UpsertAsync(SearchIndexRecord record,CancellationToken ct=default)=>store.UpsertAsync(record,ct);public Task<SearchIndexRecord?> GetAsync(string id,CancellationToken ct=default)=>store.GetAsync(id,ct);}